import 'package:flutter/material.dart';
import 'package:talkiepal/practice/ai_question_page.dart';
import 'package:talkiepal/widgets/level_menu_page.dart';

class IntermediatePage extends StatelessWidget {
  const IntermediatePage({super.key});

  static const LevelTheme _theme = LevelTheme(
    letter: 'C',
    title: 'Intermediate',
    color: Color(0xFFFF8A3D),
    darkColor: Color(0xFFD84315),
    lightColor: Color(0xFFFFB74D),
    dinoColor: Color(0xFFFFA569),
  );

  /// Topics whose questions are generated by the AI backend.
  static const Map<String, String> _aiTopics = {
    'About Me': '🙋',
    'Daily Routine': '⏰',
    'My School': '🏫',
    'Travel & Holiday': '✈️',
    'Weather & Seasons': '☀️',
    'Feelings & Emotion': '😊',
    'Places Around Town': '🏙️',
  };

  /// Every topic of this level, as named on the results screen, with its picture.
  static Map<String, String> get topicEmojis => _aiTopics;

  /// Returns an unmodifiable list of topics to prevent accidental mutations.
  static List<String> get topics => List.unmodifiable(topicEmojis.keys);

  /// Helper to navigate to the AI Question practice page.
  void _openTopic(BuildContext context, String topicKey) {
    Navigator.push(
      context,
      MaterialPageRoute(
        builder: (context) => AiQuestionPage(topic: topicKey),
      ),
    );
  }

  /// Helper to show a "coming soon" message.
  void _showComingSoon(BuildContext context) {
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('Mini Stories is coming soon! 📖'),
        backgroundColor: Color(0xFFFF8A3D),
        duration: Duration(seconds: 1),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return LevelMenuPage(
      theme: _theme,
      dinoMessage: 'Listen to my questions and pick the right answer!',
      tip: 'Listen to the question first, then tap the answer you think is right!',
      sections: [
        LevelSection(
          topics: [
            for (final topic in _aiTopics.entries)
              LevelTopic(
                emoji: topic.value,
                title: topic.key,
                onTap: (context) => _openTopic(context, topic.key),
              ),
            LevelTopic(
              emoji: '📖',
              title: 'Mini Stories',
              onTap: (context) => _showComingSoon(context),
            ),
          ],
        ),
      ],
    );
  }
}